/* eslint-disable no-restricted-syntax, no-invalid-this, stdlib/no-empty-lines-between-requires */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );
var defaults = require( './defaults.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getAs = require( './as/get.js' );
var setAs = require( './as/set.js' );

var getExpr = require( './expr/get.js' );
var setExpr = require( './expr/set.js' );

var getInitonly = require( './initonly/get.js' );
var setInitonly = require( './initonly/set.js' );

var getProperties = require( './properties/get.js' );


// VARIABLES //

var debug = logger( 'vega:formula-transform:main' );


// MAIN //

/**
* Formula transform constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {string} options.expr - formula expression string
* @param {string} options.as - output field name for the formula result
* @param {boolean} [options.initonly=false] - boolean indicating whether the formula is evaluated only when a data object is first observed
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {FormulaTransform} formula transform instance
*
* @example
* var transform = new FormulaTransform({
*     'expr': 'log(datum.x) / LN10',
*     'as': 'logx'
* });
* // returns <FormulaTransform>
*/
function FormulaTransform( options ) {
	var opts;
	var keys;
	var v;
	var k;
	var i;
	if ( !( this instanceof FormulaTransform ) ) {
		return new FormulaTransform( options );
	}
	EventEmitter.call( this );

	if ( !isObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}

	// Check for required properties...
	if ( !hasProp( options, 'expr' ) ) {
		throw new TypeError( 'invalid argument. Options argument must specify a formula expression.' );
	}
	if ( !hasProp( options, 'as' ) ) {
		throw new TypeError( 'invalid argument. Options argument must specify an output field name.' );
	}

	// Resolve the default configuration:
	opts = defaults();

	// Set internal properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
	}

	// Validate provided options by attempting to assign option values to corresponding fields...
	for ( i = 0; i < properties.length; i++ ) {
		k = properties[ i ];
		if ( !hasProp( options, k ) ) {
			continue;
		}
		v = options[ k ];
		try {
			this[ k ] = v;
		} catch ( err ) {
			debug( 'Encountered an error. Error: %s', err.message );

			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
	}
	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( FormulaTransform, EventEmitter );

/**
* Constructor name.
*
* @private
* @name name
* @memberof FormulaTransform
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( FormulaTransform, 'name', 'FormulaTransform' );

/**
* Output field name for the formula result.
*
* @name as
* @memberof FormulaTransform.prototype
* @type {string}
*
* @example
* var transform = new FormulaTransform({
*     'expr': 'log(datum.x) / LN10',
*     'as': 'logx'
* });
*
* var v = transform.as;
* // returns 'logx'
*/
setReadWriteAccessor( FormulaTransform.prototype, 'as', getAs, setAs );

/**
* Formula expression string.
*
* @name expr
* @memberof FormulaTransform.prototype
* @type {string}
*
* @example
* var transform = new FormulaTransform({
*     'expr': 'log(datum.x) / LN10',
*     'as': 'logx'
* });
*
* var v = transform.expr;
* // returns 'log(datum.x) / LN10'
*/
setReadWriteAccessor( FormulaTransform.prototype, 'expr', getExpr, setExpr );

/**
* Boolean indicating whether the formula is evaluated only when a data object is first observed.
*
* @name initonly
* @memberof FormulaTransform.prototype
* @type {boolean}
* @default false
*
* @example
* var transform = new FormulaTransform({
*     'expr': 'log(datum.x) / LN10',
*     'as': 'logx',
*     'initonly': true
* });
*
* var v = transform.initonly;
* // returns true
*/
setReadWriteAccessor( FormulaTransform.prototype, 'initonly', getInitonly, setInitonly );

/**
* Formula transform properties.
*
* @name properties
* @memberof FormulaTransform.prototype
* @type {Array<string>}
*
* @example
* var transform = new FormulaTransform({
*     'expr': 'log(datum.x) / LN10',
*     'as': 'logx'
* });
*
* var v = transform.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( FormulaTransform.prototype, 'properties', getProperties );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof FormulaTransform.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var transform = new FormulaTransform({
*     'expr': 'log(datum.x) / LN10',
*     'as': 'logx'
* });
*
* var v = transform.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( FormulaTransform.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = FormulaTransform;
